package com.example.rokidkeyboardbridge;
import android.content.*;import android.content.res.*;import android.graphics.*;import java.io.*;
/** Compares original and corrected artwork, then decodes actual animation frames. */
public final class EarProportionDeviceChecks {
 public static int run(Context c,String apk)throws Exception{int n=0;AssetManager a=AssetManager.class.getConstructor().newInstance();AssetManager.class.getMethod("addAssetPath",String.class).invoke(a,apk);Resources res=new Resources(a,c.getResources().getDisplayMetrics(),c.getResources().getConfiguration());Context image=new ContextWrapper(c){public AssetManager getAssets(){return a;}public Resources getResources(){return res;}};Bitmap old,newer;try(InputStream in=a.open("loki_body_ear_v667.png")){old=BitmapFactory.decodeStream(in);}try(InputStream in=a.open("loki_body_ear_v672.png")){newer=BitmapFactory.decodeStream(in);}StringBuilder metrics=new StringBuilder("{\"frames\":[");for(int row=0;row<2;row++)for(int col=0;col<4;col++){int os=FullBodyGestureRegions.split(old),ns=FullBodyGestureRegions.split(newer);Bitmap before=Bitmap.createBitmap(old,col*old.getWidth()/4,row==0?0:os,old.getWidth()/4,row==0?os:old.getHeight()-os),after=Bitmap.createBitmap(newer,col*newer.getWidth()/4,row==0?0:ns,newer.getWidth()/4,row==0?ns:newer.getHeight()-ns);float p=StandingProportionChecks.head(before),q=StandingProportionChecks.head(after);if(q>=p*.99f)throw new AssertionError("ear head not reduced row="+row+" col="+col+" "+p+" -> "+q);n++;if(row+col>0)metrics.append(',');metrics.append("{\"row\":").append(row).append(",\"column\":").append(col).append(",\"old\":").append(p).append(",\"new\":").append(q).append('}');before.recycle();after.recycle();}metrics.append("]}");try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"ear-v672-metrics.json"))){out.write(metrics.toString().getBytes("UTF-8"));}old.recycle();newer.recycle();FullBodyGestureRenderer renderer=new FullBodyGestureRenderer(new FullBodyGestureCanvasTest.Host(image));Bitmap sheet=Bitmap.createBitmap(720,1040,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sheet);canvas.drawColor(Color.BLACK);for(int clip=2;clip<=3;clip++){if(!FullBodyGestureRenderer.assetForClip(clip).equals(clip==2?"loki_standing_accessory_v685.png":SeatedGestureAtlas.ASSET))throw new AssertionError("old ear asset selected");n++;renderer.request(clip);long deadline=System.currentTimeMillis()+15000;while(!renderer.ready(clip)&&System.currentTimeMillis()<deadline)Thread.sleep(10);if(!renderer.ready(clip))throw new AssertionError("ear decode");n++;for(int frame=0;frame<3;frame++){canvas.save();canvas.translate(frame*240,(clip-2)*520);if(!renderer.draw(canvas,240,520,clip,frame*600,10000))throw new AssertionError("ear draw");n++;canvas.restore();}}try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"ear-v672-preview.png"))){sheet.compress(Bitmap.CompressFormat.PNG,100,out);}sheet.recycle();renderer.release();return n;}
}
